#!/usr/bin/env python3
from __future__ import annotations
import numpy as np
from numpy.typing import NDArray
Array = NDArray[np.float64]

def split(x: Array, sizes: list[int]) -> tuple[Array, Array]:
    centered=np.empty_like(x); means=[]; start=0
    for n in sizes:
        segment=x[start:start+n]; mean=float(segment.mean())
        centered[start:start+n]=segment-mean; means.append(mean); start+=n
    return centered, np.array(means)

def lift(z: Array, sizes: list[int]) -> Array:
    return np.concatenate([np.full(n,z[i]) for i,n in enumerate(sizes)])

def main() -> None:
    sizes=[2,3]; x=np.array([4.,-2.,3.,0.,6.])
    centered, means=split(x,sizes)
    print("means:",means); print("centered:",centered)
    np.testing.assert_allclose(centered+lift(means,sizes),x)
    start=0
    for n in sizes:
        assert abs(centered[start:start+n].sum())<1e-12; start+=n

if __name__ == "__main__":
    main()

